\DeclareMathOperator{\Div}{Div}
\newcommand{\ZZ}{\mathbb{Z}}
\newcommand{\NN}{\mathbb{N}}
\newcommand{\legendre}[2]{\left(\tfrac{#1}{#2}\right)}

\title{A Non-Circular Proof of the Fibonacci Law of Apparition}
\author{Aristotle}
\date{June 28, 2026}

\begin{document}

\begin{abstract}
For a prime $p$, the \emph{rank of apparition} (Fibonacci entry point)
$\alpha(p)$ is the least positive index $k$ with $p \mid F_k$, where $F$ denotes
the Fibonacci sequence $F_0=0$, $F_1=1$, $F_{n+2}=F_{n+1}+F_n$. The \emph{spine}
of apparition theory, $p \mid F_n \iff \alpha(p) \mid n$, reduces every Fibonacci
divisibility question to the single number $\alpha(p)$. We establish the classical
\emph{localisation law}: for every prime $p \ge 7$,
$\alpha(p) \mid p-1$ or $\alpha(p) \mid p+1$. The law converts the a~priori
unbounded search for $\alpha(p)$ into a bounded loop over the divisors of $p \pm
1$. Our proof is deliberately \emph{non-circular}: rather than invoking the
multiplicative order of the golden ratio modulo $p$ (itself defined through
$\alpha(p)$), it pins down the single residue $F_p \bmod p$ via the Frobenius
endomorphism of $S=(\ZZ/p)[x]/(x^2-x-1)$, obtains $F_p^2 \equiv 1 \pmod p$, and
applies Cassini's identity at $n=p-1$ with primality to split $p \mid
F_{p+1}F_{p-1}$. The development is fully machine-checked in Lean~4/Mathlib.
\end{abstract}

\maketitle

\section{Introduction}

The Fibonacci sequence $(F_n)_{n\ge 0}$ defined by $F_0=0$, $F_1=1$,
$F_{n+2}=F_{n+1}+F_n$ is a \emph{strong divisibility sequence}:
$\gcd(F_m,F_n)=F_{\gcd(m,n)}$. Hence for any modulus $m$ the indices with
$m \mid F_n$ form a principal divisibility-ideal of $\NN$.

\begin{definition}[Rank of apparition]
For $m \in \NN$, say $m$ \emph{has a rank} if there is $k>0$ with $m \mid F_k$.
The \textbf{rank of apparition} of $m$ is $\alpha(m)=\min\{k>0 : m \mid F_k\}$,
with $\alpha(m)=0$ when no such $k$ exists. (Lean: \texttt{HasRank},
\texttt{rank}.)
\end{definition}

The theory rests on existence (every $m>0$ has a rank) and the spine.

\begin{theorem}[Spine]\label{thm:spine}
If $m$ has a rank then, for all $k$, $\;m \mid F_k \iff \alpha(m) \mid k$.
\emph{(Lean: \texttt{dvd\_fib\_iff\_rank\_dvd}.)}
\end{theorem}

The central result of this paper is the following.

\begin{theorem}[Law of apparition]\label{thm:law}
For every prime $p \ge 7$, $\;\alpha(p) \mid p-1$ or $\alpha(p) \mid p+1$.
\emph{(Lean: \texttt{rank\_dvd\_pred\_or\_succ}.)}
\end{theorem}

The restriction $p \ge 7$ excludes $2,3$ (small exceptions) and $5$ (the ramified
prime: $\alpha(5)=5$ divides neither $4$ nor $6$).

\subsection{Computational payoff}
The naive algorithm for $\alpha(p)$ scans $k=1,2,3,\dots$ in time
$\Theta(\alpha(p))$, which may reach $p+1$ and is unknown a~priori.
Theorem~\ref{thm:law} replaces this with a bounded search.

\begin{quote}
\textbf{Algorithm $\mathrm{RANK}(p)$, $p\ge 7$ prime:}
(1) enumerate $D=\Div(p-1)\cup\Div(p+1)$ sorted ascending;
(2) for each $d\in D$, if $p \mid F_d$ return $d$.
\end{quote}

Theorem~\ref{thm:law} guarantees termination with a return, and
Theorem~\ref{thm:spine} guarantees that the first hit is $\alpha(p)$ (any $d$
with $p\mid F_d$ is a multiple of $\alpha(p)$). With $F_d \bmod p$ by fast
doubling in $O(\log d)$ multiplications and $|D| \le d(p-1)+d(p+1)$ candidates,
the cost is quasi-polynomial in $\log p$.

\subsection{The circularity, and how we avoid it}
Binet's formula $F_n=(\varphi^n-\psi^n)/\sqrt5$ with $\varphi,\psi$ the roots of
$x^2-x-1$ tempts an argument through the multiplicative order of $\varphi$ modulo
$p$; but that order is \emph{defined through} $\alpha(p)$, so the argument is
circular. We instead compute the rank-independent residue $F_p\bmod p$ via
Frobenius and feed it into Cassini, mentioning $\alpha(p)$ only at the final step.

\section{The spine}

\begin{lemma}[Existence]\label{lem:exist}
For $m>0$, $m$ has a rank. \emph{(Lean: \texttt{exists\_pos\_dvd\_fib}.)}
\end{lemma}

\begin{proof}[Proof sketch]
The pairs $P_k=(F_k\bmod m, F_{k+1}\bmod m)\in(\ZZ/m)^2$ lie in a finite set, so
$P_i=P_j$ for some $i<j$. The recurrence is invertible ($F_k=F_{k+2}-F_{k+1}$),
so $P_0=P_{j-i}$; as $P_0=(0,1)$, the first coordinate of $P_{j-i}$ vanishes,
giving $m\mid F_{j-i}$ with $j-i>0$.
\end{proof}

\begin{lemma}\label{lem:rankpos}
If $m$ has a rank then $\alpha(m)>0$ and $m\mid F_{\alpha(m)}$.
\emph{(Lean: \texttt{rank\_pos}, \texttt{dvd\_fib\_rank}.)}
\end{lemma}

\begin{proof}[Proof of Theorem~\ref{thm:spine}]
($\Leftarrow$) If $\alpha(m)\mid k$, write $k=\alpha(m)c$; then $F_{\alpha(m)}\mid
F_k$ (\texttt{Nat.fib\_dvd}) and $m\mid F_{\alpha(m)}$, so $m\mid F_k$.
($\Rightarrow$) If $m\mid F_k$, then using $F_{\gcd(a,b)}=\gcd(F_a,F_b)$
(\texttt{Nat.fib\_gcd}),
\[
m \mid \gcd(F_{\alpha(m)},F_k)=F_{\gcd(\alpha(m),k)}.
\]
So $g:=\gcd(\alpha(m),k)$ is a positive index with $m\mid F_g$ and
$g\le\alpha(m)$; minimality forces $g=\alpha(m)$, i.e. $\alpha(m)\mid k$.
\end{proof}

\section{A ring-theoretic Binet identity}

\begin{lemma}[Binet recurrence]\label{lem:binet}
Let $R$ be a commutative ring and $a\in R$ with $a^2=a+1$. Then for all $n\ge 0$,
\[
a^{\,n+1}=F_{n+1}\,a+F_n.
\]
\emph{(Lean: \texttt{pow\_succ\_of\_golden}.)}
\end{lemma}

\begin{proof}[Proof sketch]
Induction on $n$. Base: $a^1=F_1a+F_0=a$. Step: multiply by $a$ and use
$a^2=a+1$:
$a^{n+2}=F_{n+1}(a+1)+F_n a=(F_{n+1}+F_n)a+F_{n+1}=F_{n+2}a+F_{n+1}$.
\end{proof}

\paragraph{The golden-ratio ring.}
Fix a prime $p\ge 7$ and set $S=(\ZZ/p)[x]/(x^2-x-1)$, a free $(\ZZ/p)$-algebra of
rank $2$. Let $\varphi\in S$ be the image of $x$ and $\psi=1-\varphi$. Then
$\varphi^2=\varphi+1$, $\psi^2=\psi+1$, and
\[
\varphi+\psi=1,\quad \varphi\psi=-1,\quad (\varphi-\psi)^2
=(\varphi+\psi)^2-4\varphi\psi=1+4=5.
\]
The structure map $\iota:\ZZ/p\hookrightarrow S$ is injective. Applying
Lemma~\ref{lem:binet} to $\varphi$ and $\psi$ at $n=p-1$ and subtracting,
\begin{equation}\label{eq:diff}
\varphi^p-\psi^p=F_p\,(\varphi-\psi).
\end{equation}

\section{Pinning down $F_p \bmod p$ via Frobenius}

\begin{lemma}[Freshman's dream]\label{lem:frob}
In a commutative ring of prime characteristic $p$, $(u+v)^p=u^p+v^p$; thus
$u\mapsto u^p$ is a ring endomorphism. \emph{(Mathlib: \texttt{add\_pow\_char}.)}
\end{lemma}

Since $\operatorname{char}S=p$, Frobenius gives
\begin{equation}\label{eq:fr1}
\varphi^p+\psi^p=(\varphi+\psi)^p=1,\qquad
\varphi^p\psi^p=(\varphi\psi)^p=(-1)^p=-1,
\end{equation}
the latter because $p$ is odd, whence
\begin{equation}\label{eq:fr2}
(\varphi^p-\psi^p)^2=(\varphi^p+\psi^p)^2-4\varphi^p\psi^p=1+4=5.
\end{equation}

\begin{theorem}[$F_p^2\equiv 1$]\label{thm:fpsq}
For every prime $p\ge 7$, $\;F_p^{\,2}\equiv 1 \pmod p$.
\emph{(Lean: \texttt{fib\_sq\_mod}.)}
\end{theorem}

\begin{proof}[Proof sketch]
Square \eqref{eq:diff} and use $(\varphi-\psi)^2=5$:
$(\varphi^p-\psi^p)^2=5F_p^{\,2}$ in $S$. With \eqref{eq:fr2}, $5F_p^{\,2}=5$ in
$S$, hence $\iota(5F_p^2)=\iota(5)$. Injectivity of $\iota$ gives $5F_p^2=5$ in
$\ZZ/p$; as $p\ge 7$ implies $p\nmid 5$, cancel the unit $5$ to get $F_p^2=1$.
\end{proof}

\begin{remark}[Legendre symbol]
The same computation gives $\varphi^p-\psi^p=\pm(\varphi-\psi)$ with sign
$5^{(p-1)/2}\equiv\legendre{5}{p}\pmod p$ by Euler's criterion, so in fact
$F_p\equiv\legendre{5}{p}\pmod p$. This refinement, governed by $p\bmod 5$, seeds
Conjecture~\ref{conj:branch}. Theorem~\ref{thm:law} needs only $F_p^2\equiv 1$.
\end{remark}

\section{Cassini's identity and the dichotomy}

\begin{lemma}[Cassini]\label{lem:cassini}
Over $\ZZ$, for all $n\ge 0$, $\;F_{n+2}F_n+(-1)^n=F_{n+1}^{\,2}$.
\emph{(Lean: \texttt{cassini}.)}
\end{lemma}

\begin{proof}[Proof sketch]
Induction, or take determinants in
$\left(\begin{smallmatrix}1&1\\1&0\end{smallmatrix}\right)^n
=\left(\begin{smallmatrix}F_{n+1}&F_n\\F_n&F_{n-1}\end{smallmatrix}\right)$.
\end{proof}

\begin{theorem}[Fibonacci--Fermat law]\label{thm:ff}
For every prime $p\ge 7$, $\;p\mid F_{p-1}$ or $p\mid F_{p+1}$.
\emph{(Lean: \texttt{p\_dvd\_fib\_pred\_or\_succ}.)}
\end{theorem}

\begin{proof}[Proof sketch]
Apply Lemma~\ref{lem:cassini} at $n=p-1$. Since $p$ is odd, $(-1)^{p-1}=1$ and
$F_{p+1}F_{p-1}+1=F_p^{\,2}$. Reduce mod $p$ and use
Theorem~\ref{thm:fpsq}: $F_{p+1}F_{p-1}\equiv F_p^2-1\equiv 0\pmod p$. Primality
(Euclid's lemma) gives $p\mid F_{p+1}$ or $p\mid F_{p-1}$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:law}]
Let $p\ge 7$ be prime. By Lemma~\ref{lem:exist} it has a rank, so
Theorem~\ref{thm:spine} applies. By Theorem~\ref{thm:ff} either $p\mid F_{p-1}$,
giving $\alpha(p)\mid p-1$, or $p\mid F_{p+1}$, giving $\alpha(p)\mid p+1$.
\end{proof}

Every input to Theorem~\ref{thm:law} is proved without reference to $\alpha(p)$,
which makes the derivation non-circular.

\section{Algorithms}

\paragraph{Fibonacci mod $m$ by fast doubling.}
Using $F_{2k}=F_k(2F_{k+1}-F_k)$ and $F_{2k+1}=F_{k+1}^2+F_k^2$, the pair
$(F_d,F_{d+1})\bmod m$ is computed in $O(\log d)$ ring operations.

\paragraph{Bounded rank computation.}
Algorithm $\mathrm{RANK}(p)$ enumerates $\Div(p-1)\cup\Div(p+1)$, sorts, and
returns the least $d$ with $F_d\equiv 0\pmod p$; correctness and termination are
Theorems~\ref{thm:spine} and~\ref{thm:law}. Cost:
$O((d(p-1)+d(p+1))\log p)$ modular multiplications after factoring $p\pm 1$.

\section{Discussion and open problems}

\begin{conjecture}[Legendre branch selection]\label{conj:branch}
For odd $p\ne 5$: if $p\equiv\pm1\pmod 5$ then $\alpha(p)\mid p-1$; if
$p\equiv\pm2\pmod 5$ then $\alpha(p)\mid p+1$ (and $\alpha(p)\nmid p-1$).
Equivalently $\alpha(p)\mid p-\legendre{5}{p}$.
\end{conjecture}

\begin{conjecture}[Prime-power lifting]
For a prime $p\ne 5$ and $k\ge 1$, $\alpha(p^k)=p^{k-1}\alpha(p)$ unless $p$ is a
Wall--Sun--Sun prime (none known); unconditionally
$\alpha(p)\mid\alpha(p^k)\mid p^{k-1}\alpha(p)$.
\end{conjecture}

\begin{conjecture}[Uniform Lucas law]
For a nondegenerate Lucas sequence $U_n(P,Q)$ with discriminant $D=P^2-4Q$,
every prime $p\nmid 2QD$ satisfies $\alpha_U(p)\mid p-\legendre{D}{p}$, via
$2^{\,n-1}U_n=\sum_j\binom{n}{2j+1}P^{\,n-1-2j}D^{\,j}$.
\end{conjecture}

\begin{conjecture}[Density]
The primes with $\alpha(p)\mid p-1$ (i.e. $p\equiv\pm1\bmod 5$) have natural
density $1/2$, and likewise the $p+1$ branch, by Dirichlet's theorem on primes in
arithmetic progressions.
\end{conjecture}

\section{Formalisation notes}

The development is machine-checked in Lean~4/Mathlib. Reusable components carry
the algebra (\texttt{AdjoinRoot}, \texttt{CharP}/\texttt{add\_pow\_char} for
Frobenius, the field structure of \texttt{ZMod p}, \texttt{Nat.fib\_gcd},
\texttt{Nat.fib\_dvd}), so the core \texttt{fib\_sq\_mod} is short and auditable.
Side conditions are discharged by \texttt{decide}/\texttt{compute\_degree!} and
ring identities by \texttt{ring}/\texttt{linear\_combination}. Named results:
\texttt{exists\_pos\_dvd\_fib}, \texttt{rank\_pos}, \texttt{dvd\_fib\_rank},
\texttt{dvd\_fib\_iff\_rank\_dvd}, \texttt{pow\_succ\_of\_golden},
\texttt{fib\_sq\_mod}, \texttt{cassini}, \texttt{p\_dvd\_fib\_pred\_or\_succ},
\texttt{rank\_dvd\_pred\_or\_succ}.

\section{Conclusion}

We proved non-circularly, with full machine verification, that the Fibonacci rank
of apparition of any prime $p\ge 7$ divides $p-1$ or $p+1$. The proof isolates the
rank-independent residue $F_p\bmod p$ through the Frobenius endomorphism, derives
$F_p^2\equiv 1$, and closes with Cassini's identity and Euclid's lemma. The law
turns the computation of $\alpha(p)$ from an unbounded scan into a bounded divisor
search and points toward sharp refinements now within reach.

\end{document}

