from typing import List, Tuple

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True

def fib_pair_mod(n: int, m: int) -> Tuple[int, int]:
    if m == 1:
        return (0, 0)
    if n == 0:
        return (0, 1 % m)
    a, b = fib_pair_mod(n >> 1, m)
    c = (a * ((2 * b - a) % m)) % m
    d = (a * a + b * b) % m
    return (d, (c + d) % m) if n & 1 else (c, d)

def fib_mod(n: int, m: int) -> int:
    return fib_pair_mod(n, m)[0]

def legendre_symbol(a: int, p: int) -> int:
    a %= p
    if a == 0:
        return 0
    ls = pow(a, (p - 1) // 2, p)
    return ls - p if ls > 1 else ls

def branch_matches_legendre(limit: int = 20000) -> None:
    """
    Empirically confirm the Legendre branch-selection conjecture (C1):
        F_p == (5|p) (mod p),  and the satisfied branch of alpha(p) is
        p-1 exactly when (5|p) = +1 (i.e. p == +/-1 mod 5).
    """
    bad = 0
    for p in range(7, limit):
        if not is_prime(p):
            continue
        fp = fib_mod(p, p)
        leg = legendre_symbol(5, p)
        # engine residue identity
        assert fp % p == leg % p, f"F_p != (5|p) at p={p}"
        # Fibonacci-Fermat branch agrees with sign of (5|p)
        if leg == 1:
            assert fib_mod(p - 1, p) == 0, f"expected p|F_(p-1) at p={p}"
        else:
            assert fib_mod(p + 1, p) == 0, f"expected p|F_(p+1) at p={p}"
        bad += 0
    print(f"Legendre branch identity verified for all primes in [7, {limit}).")

if __name__ == "__main__":
    branch_matches_legendre(20000)

