function FIBPAIR(n, m):       # returns (F_n mod m, F_{n+1} mod m)
    if m == 1: return (0, 0)
    if n == 0: return (0, 1 mod m)
    (a, b) <- FIBPAIR(n >> 1, m)            # a=F_k, b=F_{k+1}, k=n//2
    c <- a*(2b - a) mod m                    # F_{2k}
    d <- (a*a + b*b) mod m                    # F_{2k+1}
    if n is odd: return (d, (c+d) mod m)
    else:        return (c, d)

function FIBMOD(n, m): return FIBPAIR(n, m).first

